// Original selected application renderer; generated by prepare_home_scene_render_controls.py.
namespace Zjcs.Official.HomeSceneUiControls
{
using Object = UnityEngine.Object;
using System;
using UnityEngine;

[ExecuteInEditMode]
[RequireComponent(typeof(MeshFilter), typeof(MeshRenderer))]
public class CustomRenderer : MonoBehaviour
{
	public Sprite Sprite;

	[ColorUsage(true, true)]
	public Color Color = Color.white;

	[Range(-1f, 1f)]
	public float Hue;

	[Range(-1f, 1f)]
	public float Saturation;

	[Range(-1f, 1f)]
	public float Lightness;

	private int mLastSpriteId;

	private Color[] mColors;

	private Vector3[] mHSLOffset;

	private Mesh mMesh;

	protected MeshRenderer mRenderer;

	private MaterialPropertyBlock mMPB;

	public static readonly int sMainTexId = Shader.PropertyToID("_MainTex");

	protected MaterialPropertyBlock MPB
	{
		get
		{


			if (mMPB == null)
			{
				mMPB = new MaterialPropertyBlock();
			}
			return mMPB;
		}
	}

	private void Awake()
	{


		mRenderer = ((Component)this).GetComponent<MeshRenderer>();
		mMesh = new Mesh();
		((Object)mMesh).name = "CustomSpriteMesh";
		((Object)mMesh).hideFlags = (HideFlags)52;
		((Component)this).GetComponent<MeshFilter>().mesh = mMesh;
	}

	private void OnDestroy()
	{
		if (Application.isPlaying)
		{
			Object.Destroy((Object)(object)mMesh);
		}
		else
		{
			Object.DestroyImmediate((Object)(object)mMesh);
		}
		mMesh = null;
	}

	private void OnEnable()
	{
		if (((Component)this).transform.hasChanged)
		{
			GenerateMesh();
			((Component)this).transform.hasChanged = false;
		}
		SetMPB();
	}

	protected virtual void SetMPB()
	{
		Texture2D val = null;
		if ((Object)(object)Sprite != (Object)null)
		{
			val = Sprite.texture;
		}
		if ((Object)(object)val != (Object)null)
		{
			MPB.SetTexture(sMainTexId, (Texture)(object)val);
			((Renderer)mRenderer).SetPropertyBlock(MPB);
		}
	}

	protected virtual void OnDidApplyAnimationProperties()
	{
		GenerateMesh();
	}

	public void GenerateMesh()
	{






		if ((Object)(object)mMesh == (Object)null)
		{
			return;
		}
		if ((Object)(object)Sprite == (Object)null)
		{
			mMesh.Clear();
			return;
		}
		int instanceID = ((Object)Sprite).GetInstanceID();
		if (mLastSpriteId != instanceID)
		{
			mMesh.Clear();
			((Object)mMesh).name = ((Object)Sprite).name;
			Vector2[] vertices = Sprite.vertices;
			int num = vertices.Length;
			Vector3[] array = new Vector3[num];
			Array.Resize(ref mColors, num);
			Array.Resize(ref mHSLOffset, num);
			for (int i = 0; i < num; i++)
			{
				array[i] = (Vector3)vertices[i];
			}
			mMesh.vertices = array;
			mMesh.uv = Sprite.uv;
			mMesh.SetTriangles(Sprite.triangles, 0, true, 0);
			mLastSpriteId = instanceID;
		}
		_ = mMesh.vertexCount;
		Array.Fill<Color>(mColors, Color);
		mMesh.colors = mColors;
		Vector3 val = new Vector3(Hue, Saturation, Lightness);
		Array.Fill<Vector3>(mHSLOffset, val);
		mMesh.SetUVs(1, mHSLOffset);
	}

	public CustomRenderer()
	{


	}
}

}
